package edu.evacuaid.service;

import edu.evacuaid.api.ApiDtos.*;
import edu.evacuaid.graph.RouteFinder;
import edu.evacuaid.graph.RouteFinder.Route;
import edu.evacuaid.model.*;
import edu.evacuaid.repo.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.util.stream.Collectors;

@Service
public class EvacuationService {
 private final BuildingRepository buildings; private final SimulationEventRepository events; private final FireScenarioRepository hazards; private final FloorBlueprintRepository blueprints; private final RouteFinder finder=new RouteFinder();
 public EvacuationService(BuildingRepository b,SimulationEventRepository e,FireScenarioRepository h,FloorBlueprintRepository f){buildings=b;events=e;hazards=h;blueprints=f;}
 @Transactional(readOnly=true) public List<BuildingDto> all(){return buildings.findAll().stream().map(this::dto).toList();}
 @Transactional(readOnly=true) public BuildingDto get(long id){return dto(require(id));}
 @Transactional public BuildingDto create(CreateBuilding request){return dto(buildings.save(new Building(request.name(),request.description())));}
 @Transactional public BuildingDto update(long id,CreateBuilding request){Building b=require(id);b.setName(request.name());b.setDescription(request.description());return dto(b);}
 @Transactional public BuildingDto addPlace(long id,PlaceInput input){Building b=require(id);if(b.getPlaces().stream().anyMatch(p->p.getCode().equalsIgnoreCase(input.code())))throw new IllegalArgumentException("That location code already exists.");if(input.floorNumber()<1||input.floorNumber()>20)throw new IllegalArgumentException("Floor number must be between 1 and 20.");Place p=switch(input.type().toUpperCase()){case "ROOM"->new Room(input.code(),input.label(),input.x(),input.y());case "JUNCTION"->new Junction(input.code(),input.label(),input.x(),input.y());case "STAIR"->new Staircase(input.code(),input.label(),input.x(),input.y());case "EXIT"->new EmergencyExit(input.code(),input.label(),input.x(),input.y());default->throw new IllegalArgumentException("Type must be ROOM, JUNCTION, STAIR, or EXIT.");};p.setFloorNumber(input.floorNumber());b.addPlace(p);return dto(b);}
 @Transactional public BuildingDto positionPlace(long id,String code,PositionInput position){Building b=require(id);Place p=b.getPlaces().stream().filter(x->x.getCode().equals(code)).findFirst().orElseThrow(()->new IllegalArgumentException("Location not found: "+code));p.setX(position.x());p.setY(position.y());return dto(b);}
 @Transactional public BuildingDto addPassage(long id,PassageInput input){Building b=require(id);Set<String> codes=new HashSet<>();b.getPlaces().forEach(p->codes.add(p.getCode()));if(!codes.contains(input.fromCode())||!codes.contains(input.toCode()))throw new IllegalArgumentException("Passage endpoints must be existing location codes.");if(input.fromCode().equals(input.toCode())||b.getPassages().stream().anyMatch(p->p.getCode().equalsIgnoreCase(input.code())))throw new IllegalArgumentException("Passage code must be unique and endpoints must differ.");b.addPassage(new Passage(input.code(),input.fromCode(),input.toCode(),input.cost()));return dto(b);}
 @Transactional public void delete(long id){Building b=require(id);blueprints.deleteByBuilding_Id(id);hazards.deleteAll(hazards.findByBuildingIdAndActiveTrue(id));buildings.delete(b);}
 @Transactional public BuildingDto sample(){Optional<Building> saved=buildings.findAll().stream().filter(b->b.getName().equals("Northstar Learning Centre")).findFirst();if(saved.isPresent()){Building existing=saved.get();if(existing.getPlaces().stream().noneMatch(p->p.getCode().equals("F2-CLASS")))addSecondFloor(existing);return dto(existing);}return buildings.findAll().stream().filter(b->b.getName().equals("Northstar Learning Centre")).findFirst().map(this::dto).orElseGet(()->{
  Building b=new Building("Northstar Learning Centre","Sample two-wing academic building");
  b.addPlace(new Room("LAB","Computer Lab",100,100));b.addPlace(new Room("LIB","Library",100,300));b.addPlace(new Room("OFF","Faculty Office",100,500));
  b.addPlace(new Junction("J1","North Junction",320,180));b.addPlace(new Junction("J2","Central Junction",500,320));b.addPlace(new Junction("J3","South Junction",320,470));b.addPlace(new Junction("J4","East Junction",700,320));
  b.addPlace(new EmergencyExit("EXIT-A","West Exit",850,150));b.addPlace(new EmergencyExit("EXIT-B","East Exit",850,500));b.addPlace(new Staircase("STAIR-1","Protected Stair · Floor 1",500,500));
  Room f2room=new Room("F2-CLASS","Floor 2 Classroom",150,170);f2room.setFloorNumber(2);b.addPlace(f2room);Junction f2hall=new Junction("F2-HALL","Floor 2 Junction",430,300);f2hall.setFloorNumber(2);b.addPlace(f2hall);Staircase f2stairs=new Staircase("STAIR-2","Protected Stair · Floor 2",500,500);f2stairs.setFloorNumber(2);b.addPlace(f2stairs);EmergencyExit f2exit=new EmergencyExit("EXIT-C","Floor 2 Exit",850,220);f2exit.setFloorNumber(2);b.addPlace(f2exit);
  String[][] es={{"P1","LAB","J1","3"},{"P2","LIB","J1","2"},{"P3","OFF","J3","3"},{"P4","J1","J2","3"},{"P5","J2","J3","2"},{"P6","J2","J4","3"},{"P7","J3","STAIR-1","2"},{"P9","J4","EXIT-A","2"},{"P10","J4","EXIT-B","2"},{"P11","J1","EXIT-A","8"},{"P12","J3","EXIT-B","7"},{"P13","F2-CLASS","F2-HALL","2"},{"P14","F2-HALL","STAIR-2","3"},{"P15","STAIR-2","EXIT-C","3"},{"STAIR-CONNECTOR","STAIR-1","STAIR-2","5"}};
  for(String[] e:es)b.addPassage(new Passage(e[0],e[1],e[2],Double.parseDouble(e[3])));return dto(buildings.save(b));});}
 private void addSecondFloor(Building b){Room r=new Room("F2-CLASS","Floor 2 Classroom",150,170);r.setFloorNumber(2);b.addPlace(r);Junction j=new Junction("F2-HALL","Floor 2 Junction",430,300);j.setFloorNumber(2);b.addPlace(j);Staircase s=new Staircase("STAIR-2","Protected Stair · Floor 2",500,500);s.setFloorNumber(2);b.addPlace(s);EmergencyExit x=new EmergencyExit("EXIT-C","Floor 2 Exit",850,220);x.setFloorNumber(2);b.addPlace(x);String lowerStair=b.getPlaces().stream().filter(Staircase.class::isInstance).filter(p->p.getFloorNumber()==1).map(Place::getCode).findFirst().orElseThrow();String[][] links={{"P13","F2-CLASS","F2-HALL","2"},{"P14","F2-HALL","STAIR-2","3"},{"P15","STAIR-2","EXIT-C","3"},{"STAIR-CONNECTOR",lowerStair,"STAIR-2","5"}};for(String[] e:links)b.addPassage(new Passage(e[0],e[1],e[2],Double.parseDouble(e[3])));}
 @Transactional public PassageDto block(long id,String code,boolean blocked){Building b=require(id);Passage p=b.getPassages().stream().filter(x->x.getCode().equals(code)).findFirst().orElseThrow(()->new IllegalArgumentException("Passage not found: "+code));p.setBlocked(blocked);events.save(new SimulationEvent(id,blocked?"BLOCK":"RESTORE",null,null,null,code));return new PassageDto(p.getCode(),p.getFromCode(),p.getToCode(),p.getCost(),p.isBlocked());}
 @Transactional public List<RouteDto> route(long id,RouteRequest req){Building b=require(id);Set<String> hazardEdges=activeHazards(id).map(h->csvSet(h.getHazardPassageCodes())).orElseGet(Set::of);List<RouteDto> result=findRoutes(b,req.startCode(),req.exitCode(),req.automaticExit(),hazardEdges);recordRoute(id,req.startCode(),result);return result;}
 @Transactional public FireScenarioResult simulateFire(long id,FireScenarioRequest req){Building b=require(id);if(b.getPlaces().stream().noneMatch(p->p.getCode().equals(req.originCode())))throw new IllegalArgumentException("Fire origin location was not found.");if(b.getPlaces().stream().noneMatch(p->p.getCode().equals(req.startCode())))throw new IllegalArgumentException("Starting location was not found.");
  Map<String,Integer> distance=new HashMap<>();ArrayDeque<String> queue=new ArrayDeque<>();distance.put(req.originCode(),0);queue.add(req.originCode());while(!queue.isEmpty()){String code=queue.remove();int depth=distance.get(code);if(depth>=req.spreadSteps())continue;for(Passage p:b.getPassages()){String next=p.getFromCode().equals(code)?p.getToCode():p.getToCode().equals(code)?p.getFromCode():null;if(next!=null&&!distance.containsKey(next)){distance.put(next,depth+1);queue.add(next);}}}
  Set<String> reached=distance.keySet();Set<String> riskyEdges=b.getPassages().stream().filter(p->reached.contains(p.getFromCode())||reached.contains(p.getToCode())).map(Passage::getCode).collect(Collectors.toCollection(LinkedHashSet::new));
  hazards.findByBuildingIdAndActiveTrue(id).forEach(FireScenario::deactivate);FireScenario scenario=hazards.save(new FireScenario(id,req.originCode(),req.spreadSteps(),String.join(",",reached),String.join(",",riskyEdges)));
  List<RouteDto> route=findRoutes(b,req.startCode(),req.exitCode(),req.automaticExit(),riskyEdges);recordRoute(id,req.startCode(),route);events.save(new SimulationEvent(id,"FIRE_SCENARIO",req.originCode(),route.isEmpty()?null:route.get(0).exitCode(),route.isEmpty()?null:route.get(0).cost(),"steps="+scenario.getSpreadSteps()+"; hazards="+String.join(",",riskyEdges)));
  return new FireScenarioResult(scenario.getOriginCode(),scenario.getSpreadSteps(),List.copyOf(reached),List.copyOf(riskyEdges),route);
 }
 @Transactional public void clearFire(long id){require(id);hazards.findByBuildingIdAndActiveTrue(id).forEach(FireScenario::deactivate);events.save(new SimulationEvent(id,"FIRE_CLEARED",null,null,null,""));}
 @Transactional(readOnly=true) public List<FloorDto> floors(long id){Building b=require(id);Set<Integer> fs=b.getPlaces().stream().map(Place::getFloorNumber).collect(Collectors.toCollection(TreeSet::new));if(fs.isEmpty())fs.add(1);Set<Integer> images=blueprints.findByBuilding_Id(id).stream().map(FloorBlueprint::getFloorNumber).collect(Collectors.toSet());return fs.stream().map(f->new FloorDto(f,images.contains(f))).toList();}
 @Transactional(readOnly=true) public List<SimulationEvent> history(){return events.findTop100ByOrderByCreatedAtDesc();}
 @Transactional(readOnly=true) public Building requireBuilding(long id){return require(id);}
 private List<RouteDto> findRoutes(Building b,String start,String exit,boolean automatic,Set<String> excluded){if(b.getPlaces().stream().noneMatch(p->p.getCode().equals(start)))throw new IllegalArgumentException("Starting location was not found.");List<Place> exits=b.getPlaces().stream().filter(EmergencyExit.class::isInstance).filter(p->automatic||p.getCode().equals(exit)).toList();List<Route> routes=new ArrayList<>();for(Place e:exits)routes.addAll(finder.alternatives(b,start,e.getCode(),3,excluded));routes.sort(Comparator.comparingDouble(Route::cost));return routes.stream().limit(6).map(r->new RouteDto(r.nodes(),r.cost(),r.nodes().get(r.nodes().size()-1))).toList();}
 private void recordRoute(long id,String start,List<RouteDto> routes){String flat=routes.isEmpty()?"":String.join(";",routes.stream().map(r->String.join(",",r.nodes())).toList());events.save(new SimulationEvent(id,routes.isEmpty()?"NO_ROUTE":"ROUTE",start,routes.isEmpty()?null:routes.get(0).exitCode(),routes.isEmpty()?null:routes.get(0).cost(),flat));}
 private Optional<FireScenario> activeHazards(long id){return hazards.findFirstByBuildingIdAndActiveTrueOrderByCreatedAtDesc(id);}
 private Set<String> csvSet(String data){if(data==null||data.isBlank())return Set.of();return new HashSet<>(Arrays.asList(data.split(",")));}
 private Building require(long id){return buildings.findById(id).orElseThrow(()->new NoSuchElementException("Building not found: "+id));}
 private BuildingDto dto(Building b){Optional<FireScenario> h=activeHazards(b.getId());List<Integer> floors=b.getPlaces().stream().map(Place::getFloorNumber).distinct().sorted().toList();if(floors.isEmpty())floors=List.of(1);return new BuildingDto(b.getId(),b.getName(),b.getDescription(),b.getPlaces().stream().map(p->new PlaceDto(p.getCode(),p.getLabel(),p.getType(),p.getX(),p.getY(),p.getFloorNumber())).toList(),b.getPassages().stream().map(p->new PassageDto(p.getCode(),p.getFromCode(),p.getToCode(),p.getCost(),p.isBlocked())).toList(),h.map(FireScenario::getOriginCode).orElse(null),h.map(FireScenario::getSpreadSteps).orElse(0),h.map(x->List.copyOf(csvSet(x.getHazardPassageCodes()))).orElse(List.of()));}
}
